using System;
using System.Collections.Generic;
using System.Linq;
using AiDotNet.Tensors.Engines;
using AiDotNet.Tensors.Engines.Autodiff;
using AiDotNet.Tensors.LinearAlgebra;
using Xunit;

namespace AiDotNet.Tensors.Tests.Engines;

/// <summary>torch.grid_sampler_3d for every mode, padding and corner alignment against PyTorch float64.</summary>
[Collection("EngineCurrentGlobalState")]
public class TorchGridSample3DTests
{
    private readonly CpuEngine _engine = new CpuEngine();

    // ((i * mul mod m) - shift) * scale, the same deterministic fill the torch reference used. The grid spans
    // [-1.26, 1.26], so samples fall outside the volume and exercise the padding modes.
    private static Tensor<double> W(int[] shape, int mod, int mul, int shift, double scale = 0.1)
        => new Tensor<double>(Enumerable.Range(0, shape.Aggregate(1, (a, b) => a * b)).Select(i => (i * mul % mod - shift) * scale).ToArray(), shape);

    private static void Close(double[] expected, Tensor<double> actual, string what, double tolerance = 1e-12)
    {
        Assert.Equal(expected.Length, actual.Length);
        for (int i = 0; i < expected.Length; i++)
            Assert.True(Math.Abs(expected[i] - actual.GetFlat(i)) <= tolerance * Math.Max(1, Math.Abs(expected[i])),
                $"{what}[{i}]: torch {expected[i]:R}, ours {actual.GetFlat(i):R}");
    }

