    [Theory]
    [InlineData(GridSampleMode.Bilinear, GridSamplePadding.Zeros, false)]
    [InlineData(GridSampleMode.Bilinear, GridSamplePadding.Zeros, true)]
    [InlineData(GridSampleMode.Bilinear, GridSamplePadding.Border, false)]
    [InlineData(GridSampleMode.Bilinear, GridSamplePadding.Border, true)]
    [InlineData(GridSampleMode.Bilinear, GridSamplePadding.Reflection, false)]
    [InlineData(GridSampleMode.Bilinear, GridSamplePadding.Reflection, true)]
    [InlineData(GridSampleMode.Nearest, GridSamplePadding.Zeros, false)]
    [InlineData(GridSampleMode.Nearest, GridSamplePadding.Zeros, true)]
    [InlineData(GridSampleMode.Nearest, GridSamplePadding.Border, false)]
    [InlineData(GridSampleMode.Nearest, GridSamplePadding.Border, true)]
    [InlineData(GridSampleMode.Nearest, GridSamplePadding.Reflection, false)]
    [InlineData(GridSampleMode.Nearest, GridSamplePadding.Reflection, true)]
    public void GridSample3D_MatchesTorch(GridSampleMode mode, GridSamplePadding padding, bool alignCorners)
    {
        string key = $"{mode.ToString().ToLowerInvariant()}_{padding.ToString().ToLowerInvariant()}_{(alignCorners ? "a" : "n")}";
        var x = W(new[] { 2, 2, 3, 4, 5 }, 37, 7, 18);
        var grid = W(new[] { 2, 2, 3, 2, 3 }, 29, 11, 14, 0.09);
        using var tape = new GradientTape<double>();
        var y = _engine.TensorGridSample3D(x, grid, mode, padding, alignCorners);
        Assert.Equal(new[] { 2, 2, 2, 3, 2 }, y.Shape.ToArray());
        Close(Torch[key], y, key);
        var loss = _engine.ReduceSum(_engine.TensorMultiply(y, W(y.Shape.ToArray(), 13, 4, 6)), null, false);
        var grads = tape.ComputeGradients(loss, new[] { x, grid });
        Close(Torch[key + "_dx"], grads[x], key + " dx");
        Close(Torch[key + "_dg"], grads[grid], key + " dgrid", 1e-11);
    }
